TypeScript (async generator pattern):

// consumer.ts (example)
async function consumeStream(stream) {
  const it = stream[Symbol.asyncIterator]();
  for await (const evt of it) {
    if (evt.type === 'token') {
      process.stdout.write(evt.text);
    } else if (evt.type === 'structured') {
      // incremental JSON object chunk (may come as partials)
      try {
        const obj = stream.schemaAssembler.append(evt);
        if (obj.complete) {
          handleStructured(obj.value);
        }
      } catch (e) {
        // emit validation event, do not throw
        console.warn('schema validation', e.message);
      }
    } else if (evt.type === 'tool_call') {
      const result = await runTool(evt.name, evt.args);
      await stream.sendToolResult(result); // resume point sent back to runtime
    }
  }
}


Python (generator + send semantics):

# consumer.py
def consume_stream(stream):
    gen = stream.generator()  # yields events
    event = next(gen)
    while True:
        if event['type'] == 'token':
            print(event['text'], end='')
            event = gen.send(None)
        elif event['type'] == 'tool_call':
            out = run_tool(event['name'], event['args'])
            event = gen.send({'tool_result': out})
        elif event['type'] == 'structured':
            # assembler holds partials until complete
            assembler = stream.assembler
            assembler.append(event['chunk'])
            if assembler.complete():
                handle_structured(assembler.value())
            event = gen.send(None)


Go (channel-driven):

// consumer.go
for evt := range stream.Chan {
    switch evt.Type {
    case TokenEvent:
        fmt.Print(evt.Text)
    case ToolCallEvent:
        res := runTool(evt.Name, evt.Args)
        // send back onto resume channel
        stream.Resume <- ToolResult{ID: evt.ID, Result: res}
    case StructuredEvent:
        stream.Assembler.Append(evt.Chunk)
        if stream.Assembler.Complete() {
            handleStructured(stream.Assembler.Value())
        }
    }
}
